def rle(s):
    if not s:
        return ''
    out = []
    cur = s[0]
    n = 1
    for ch in s[1:]:
        if ch == cur:
            n += 1
        else:
            out.append(cur + str(n))
            cur = ch
            n = 1
    out.append(cur + str(n))
